//! Pinned native mutable Cynefin returned plain model, domains and transitions.
use pele::compat::{
    diagrams::cynefin::{Cynefin, CynefinModel},
    public::*,
    text::MetricsResources,
    *,
};
use serde_json::Value as Json;
use sha2::{Digest, Sha256};
use std::sync::{
    atomic::{AtomicUsize, Ordering},
    Arc,
};
fn reference(a: &Atom) -> u32 {
    if let Atom::Ref(i) = a {
        *i
    } else {
        panic!("reference")
    }
}
fn root(g: &ModelGraph) -> u32 {
    reference(&g.root)
}
fn field<'a>(g: &'a ModelGraph, id: u32, key: &str) -> &'a Atom {
    &g.nodes[id as usize]
        .properties()
        .iter()
        .find(|p| g.strings[p.key as usize].is(key))
        .unwrap()
        .value
}
fn set(g: &mut ModelGraph, id: u32, key: &str, v: Atom) {
    if let Some(i) = g.nodes[id as usize]
        .properties()
        .iter()
        .position(|p| g.strings[p.key as usize].is(key))
    {
        g.nodes[id as usize].properties_mut()[i].value = v;
    } else {
        let k = g.strings.len() as u32;
        g.strings.push(key.into());
        g.nodes[id as usize].properties_mut().push(Property {
            key: k,
            value: v,
            flags: 7,
        });
    }
    if let Node::Array { length, .. } = &mut g.nodes[id as usize] {
        if let Ok(i) = key.parse::<u32>() {
            if i < u32::MAX && i.to_string() == key && i >= *length {
                *length = i + 1;
            }
        }
    }
}
fn string(g: &mut ModelGraph, s: &str) -> Atom {
    let i = g.strings.len() as u32;
    g.strings.push(s.into());
    Atom::String(i)
}
fn object(g: &mut ModelGraph) -> u32 {
    let i = g.nodes.len() as u32;
    g.nodes.push(Node::Object { properties: vec![] });
    i
}
fn array(g: &mut ModelGraph, values: Vec<Atom>) -> u32 {
    let i = g.nodes.len() as u32;
    g.nodes.push(Node::Array {
        length: values.len() as u32,
        properties: vec![],
    });
    for (n, a) in values.into_iter().enumerate() {
        set(g, i, &n.to_string(), a)
    }
    i
}
fn keys(g: &ModelGraph, id: u32) -> Vec<String> {
    g.nodes[id as usize]
        .properties()
        .iter()
        .map(|p| g.strings[p.key as usize].well_formed().unwrap())
        .collect()
}
fn fingerprint(g: &ModelGraph) -> String {
    serde_json::to_string(g).unwrap()
}
fn hash(s: &str) -> String {
    format!("{:x}", Sha256::digest(s.as_bytes()))
}
struct Counted {
    parses: Arc<AtomicUsize>,
    renders: Arc<AtomicUsize>,
}
impl DiagramModule for Counted {
    type Model = CynefinModel;
    fn descriptor(&self) -> ModuleDescriptor {
        Cynefin.descriptor()
    }
    fn parse(&self, c: ParseContext<'_>) -> Result<Self::Model, PeleError> {
        self.parses.fetch_add(1, Ordering::SeqCst);
        Cynefin.parse(c)
    }
    fn render(
        &self,
        m: &Self::Model,
        c: &Object,
        o: &RenderSettings,
        h: &mut dyn RenderResources,
    ) -> Result<Rendered, PeleError> {
        Cynefin.render(m, c, o, h)
    }
}
impl PublicDiagramModule for Counted {
    type PublicState = <Cynefin as PublicDiagramModule>::PublicState;
    fn model_schema(&self) -> &'static ModelSchema {
        Cynefin.model_schema()
    }
    fn create_public(&self, m: &Self::Model) -> Result<Self::PublicState, PeleError> {
        Cynefin.create_public(m)
    }
    fn export_public(&self, s: &Self::PublicState) -> Result<ModelGraph, PeleError> {
        Cynefin.export_public(s)
    }
    fn apply_public(&self, s: &mut Self::PublicState, g: ModelGraph) -> Result<(), PeleError> {
        Cynefin.apply_public(s, g)
    }
    fn invoke_public(
        &self,
        s: &mut Self::PublicState,
        call: MethodCall,
        c: &Object,
        h: &mut dyn RenderResources,
    ) -> Result<Atom, PublicError> {
        Cynefin.invoke_public(s, call, c, h)
    }
    fn render_public(
        &self,
        s: &mut Self::PublicState,
        c: &Object,
        o: &RenderSettings,
        h: &mut dyn RenderResources,
    ) -> Result<Rendered, PeleError> {
        self.renders.fetch_add(1, Ordering::SeqCst);
        Cynefin.render_public(s, c, o, h)
    }
}
struct Host<'a>(&'a Json);
impl RenderResources for Host<'_> {
    fn text_width(&mut self, r: TextRequest<'_>) -> Result<f64, PeleError> {
        if self.0["measure"] == "fixed" {
            Ok(r.text.encode_utf16().count() as f64
                * r.size
                * if r.style & 1 != 0 { 0.71 } else { 0.6 })
        } else {
            MetricsResources.text_width(r)
        }
    }
    fn icon(&mut self, name: &str) -> Result<Option<TrustedSvg>, PeleError> {
        Ok(self.0["icons"][name]
            .as_str()
            .map(|s| TrustedSvg::from_trusted_markup(s.into())))
    }
}
#[test]
fn historical_cynefin_corpus_matches_through_mutable_public_documents() {
    let fixture: Json =
        serde_json::from_str(include_str!("../../../fixtures/pele/cynefin.json")).unwrap();
    let mut engine = PublicEngine::empty();
    engine.register(Cynefin);
    let mut failures = Vec::new();
    for c in fixture["cases"].as_array().unwrap() {
        let options: RenderOptions = serde_json::from_value(c["options"].clone()).unwrap();
        let actual = engine
            .parse(c["source"].as_str().unwrap(), &options.parse)
            .and_then(|mut d| d.render(&options, &mut Host(&c["host"])));
        let actual = match actual {
            Ok(r) => {
                let mut r = serde_json::to_value(r).unwrap();
                if c["expected"]["result"].get("svgSha256").is_some() {
                    let svg = r.as_object_mut().unwrap().remove("svg").unwrap();
                    r["svgSha256"] = hash(svg.as_str().unwrap()).into();
                }
                serde_json::json!({"result":r})
            }
            Err(e) => serde_json::json!({"error":e}),
        };
        let expected = if c["expected"].get("error").is_some() {
            serde_json::json!({"error":c["expected"]["error"]})
        } else {
            serde_json::json!({"result":c["expected"]["result"]})
        };
        if actual != expected {
            failures.push((c["id"].clone(), actual, expected));
        }
    }
    assert!(
        failures.is_empty(),
        "{} historical cynefin mismatches: {:?}",
        failures.len(),
        failures.iter().take(3).collect::<Vec<_>>()
    );
}
fn canonical(g: &ModelGraph) -> Json {
    use std::collections::{HashMap, VecDeque};
    fn atom(
        g: &ModelGraph,
        a: &Atom,
        ids: &mut HashMap<u32, usize>,
        queue: &mut VecDeque<u32>,
    ) -> Json {
        match a {
            Atom::Undefined => serde_json::json!(["undefined"]),
            Atom::Null => serde_json::json!(["null"]),
            Atom::Bool(v) => serde_json::json!(["bool", v]),
            Atom::Number(v) => serde_json::json!(["number", format!("{:016x}", v.to_bits())]),
            Atom::String(i) => serde_json::json!(["string", g.strings[*i as usize].0]),
            Atom::Ref(id) => {
                let next = ids.len();
                let index = *ids.entry(*id).or_insert_with(|| {
                    queue.push_back(*id);
                    next
                });
                serde_json::json!(["ref", index])
            }
            Atom::BuiltinFunction(id) => serde_json::json!(["builtin", id]),
            Atom::HostReference(id) => serde_json::json!(["host", id]),
        }
    }
    let mut ids = HashMap::new();
    let mut queue = VecDeque::new();
    let root = atom(g, &g.root, &mut ids, &mut queue);
    let mut nodes = Vec::new();
    while let Some(id) = queue.pop_front() {
        let n = &g.nodes[id as usize];
        let mut out = serde_json::json!({"kind":match n{Node::Error{..}=>"error",Node::Instance{..}=>"instance",Node::Object{..}=>"object",Node::Array{..}=>"array",Node::Map{..}=>"map",Node::Set{..}=>"set",Node::Date{..}=>"date"}});
        match n {
            Node::Error { error_type, .. } => {
                out["errorType"] = serde_json::to_value(error_type).unwrap()
            }
            Node::Instance { prototype, .. } => out["prototype"] = prototype.0.into(),
            Node::Array { length, .. } => out["length"] = (*length).into(),
            Node::Map { entries, .. } => {
                out["entries"] = entries
                    .iter()
                    .map(|(k, v)| {
                        serde_json::json!([
                            atom(g, k, &mut ids, &mut queue),
                            atom(g, v, &mut ids, &mut queue)
                        ])
                    })
                    .collect()
            }
            Node::Set { values, .. } => {
                out["values"] = values
                    .iter()
                    .map(|v| atom(g, v, &mut ids, &mut queue))
                    .collect()
            }
            _ => {}
        }
        let mut properties = n.properties().iter().collect::<Vec<_>>();
        let index = |p: &&Property| {
            g.strings[p.key as usize].well_formed().and_then(|s| {
                s.parse::<u32>()
                    .ok()
                    .filter(|n| *n != u32::MAX && n.to_string() == s)
            })
        };
        properties.sort_by(|a, b| match (index(a), index(b)) {
            (Some(x), Some(y)) => x.cmp(&y),
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            _ => std::cmp::Ordering::Equal,
        });
        out["properties"] = properties
            .into_iter()
            .map(|p| {
                serde_json::json!([
                    g.strings[p.key as usize].0,
                    atom(g, &p.value, &mut ids, &mut queue),
                    p.flags
                ])
            })
            .collect();
        nodes.push(out);
    }
    serde_json::json!({"root":root,"nodes":nodes})
}
fn selector(g: &ModelGraph, path: &[Json]) -> Atom {
    let mut value = g.root.clone();
    for key in path {
        let id = reference(&value);
        value = if let Some(k) = key.get("map") {
            let Node::Map { entries, .. } = &g.nodes[id as usize] else {
                panic!("map")
            };
            entries.iter().find(|(k0,_)|matches!(k0,Atom::String(i)if g.strings[*i as usize].is(k.as_str().unwrap()))).unwrap().1.clone()
        } else {
            let key = key
                .as_str()
                .map(str::to_string)
                .unwrap_or_else(|| key.as_u64().unwrap().to_string());
            g.nodes[id as usize]
                .properties()
                .iter()
                .find(|p| g.strings[p.key as usize].is(&key))
                .map_or(Atom::Undefined, |p| p.value.clone())
        };
    }
    value
}
fn value(g: &mut ModelGraph, v: &Json) -> Atom {
    match v {
        Json::Null => Atom::Null,
        Json::Bool(v) => Atom::Bool(*v),
        Json::Number(v) => Atom::Number(v.as_f64().unwrap()),
        Json::String(s) => string(g, s),
        Json::Array(values) => {
            let values = values.iter().map(|v| value(g, v)).collect();
            Atom::Ref(array(g, values))
        }
        Json::Object(o) => {
            if let Some(record) = o.get("record") {
                let id = object(g);
                for entry in record.as_array().unwrap() {
                    let key = entry[0].as_str().unwrap();
                    let v = value(g, &entry[1]);
                    set(g, id, key, v)
                }
                return Atom::Ref(id);
            }
            if let Some(path) = o.get("ref") {
                return selector(g, path.as_array().unwrap());
            }
            if o.contains_key("undefined") {
                return Atom::Undefined;
            }
            if let Some(units) = o.get("utf16") {
                let id = g.strings.len() as u32;
                g.strings.push(JsString(
                    units
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|n| n.as_u64().unwrap() as u16)
                        .collect(),
                ));
                return Atom::String(id);
            }
            if let Some(n) = o.get("number") {
                return Atom::Number(match n.as_str().unwrap() {
                    "nan" => f64::NAN,
                    "inf" => f64::INFINITY,
                    "-inf" => f64::NEG_INFINITY,
                    "-0" => -0.,
                    _ => panic!("number"),
                });
            }
            let id = object(g);
            for (k, v) in o {
                let value = value(g, v);
                set(g, id, k, value)
            }
            Atom::Ref(id)
        }
    }
}
fn public_error(e: &PublicError) -> Json {
    match e {
        PublicError::Pele(e) => {
            serde_json::json!({"name":e.name,"message":e.message,"code":e.code,"type":e.diagram_type,"line":e.line,"column":e.column})
        }
        PublicError::JavaScript { name, .. } => {
            serde_json::json!({"name":match name{JavaScriptErrorKind::TypeError=>"TypeError",JavaScriptErrorKind::RangeError=>"RangeError",_=>"Error"}})
        }
        _ => panic!("host error"),
    }
}
#[test]
fn pinned_cynefin_mutable_graph_methods_and_complete_svg_vectors() {
    let cases: Json = serde_json::from_str(FLOW_VECTORS).unwrap();
    let mut engine = PublicEngine::empty();
    engine.register(Cynefin);
    for c in cases.as_array().unwrap() {
        let options: RenderOptions = serde_json::from_value(c["options"].clone()).unwrap();
        let mut doc = engine
            .parse(c["source"].as_str().unwrap(), &options.parse)
            .unwrap();
        assert_eq!(
            canonical(&doc.snapshot().unwrap()),
            c["initial"],
            "initial {}",
            c["id"]
        );
        for step in c["steps"].as_array().unwrap() {
            let op = &step["op"];
            let actual = if let Some(name) = op["method"].as_str() {
                let method = doc
                    .model_schema()
                    .methods
                    .iter()
                    .find(|m| m.name == name)
                    .unwrap()
                    .id;
                let mut g = doc.snapshot().unwrap();
                let receiver = g.root.clone();
                let args = op["args"].as_array().map_or(&[][..], Vec::as_slice);
                let arguments = args.iter().map(|v| value(&mut g, v)).collect();
                doc.apply(doc.revision(), g).unwrap();
                let out = doc
                    .invoke(
                        doc.revision(),
                        MethodCall {
                            method,
                            receiver,
                            arguments,
                        },
                        &mut MetricsResources,
                    )
                    .unwrap();
                match out.result {
                    Ok(result) => {
                        let mut g = out.graph;
                        if let Some(key) = op["store"].as_str() {
                            let id = root(&g);
                            set(&mut g, id, key, result.clone());
                            doc.apply(doc.revision(), g.clone()).unwrap();
                        }
                        g.root = result;
                        serde_json::json!({"result":canonical(&g)})
                    }
                    Err(e) => serde_json::json!({"error":public_error(&e)}),
                }
            } else {
                let mut g = doc.snapshot().unwrap();
                if let Some(path) = op["set"].as_array() {
                    let target = reference(&selector(&g, &path[..path.len() - 1]));
                    let key = path
                        .last()
                        .unwrap()
                        .as_str()
                        .map(str::to_string)
                        .unwrap_or_else(|| path.last().unwrap().as_u64().unwrap().to_string());
                    let v = value(&mut g, &op["value"]);
                    set(&mut g, target, &key, v)
                } else if let Some(path) = op["delete"].as_array() {
                    let target = reference(&selector(&g, &path[..path.len() - 1]));
                    let key = path
                        .last()
                        .unwrap()
                        .as_str()
                        .map(str::to_owned)
                        .unwrap_or_else(|| path.last().unwrap().as_u64().unwrap().to_string());
                    g.nodes[target as usize]
                        .properties_mut()
                        .retain(|p| !g.strings[p.key as usize].is(&key));
                } else if let Some(path) = op["reverse"].as_array() {
                    let id = reference(&selector(&g, path));
                    let Node::Array { length, .. } = g.nodes[id as usize] else {
                        panic!("array")
                    };
                    let values = (0..length)
                        .map(|i| field(&g, id, &i.to_string()).clone())
                        .rev()
                        .collect::<Vec<_>>();
                    for (i, v) in values.into_iter().enumerate() {
                        set(&mut g, id, &i.to_string(), v)
                    }
                } else if let Some(path) = op["mapDelete"].as_array() {
                    let id = reference(&selector(&g, &path[..path.len() - 1]));
                    let key = path.last().unwrap().as_str().unwrap();
                    let Node::Map { entries, .. } = &mut g.nodes[id as usize] else {
                        panic!("map")
                    };
                    entries.retain(
                        |(k, _)| !matches!(k,Atom::String(i)if g.strings[*i as usize].is(key)),
                    )
                } else if let Some(path) = op["mapSet"].as_array() {
                    let id = reference(&selector(&g, path));
                    let key = value(&mut g, &op["key"]);
                    let v = value(&mut g, &op["value"]);
                    let Node::Map { entries, .. } = &mut g.nodes[id as usize] else {
                        panic!("map")
                    };
                    let equal = |a: &Atom, b: &Atom| match (a, b) {
                        (Atom::String(a), Atom::String(b)) => {
                            g.strings[*a as usize] == g.strings[*b as usize]
                        }
                        (Atom::Number(a), Atom::Number(b)) => a == b || a.is_nan() && b.is_nan(),
                        (Atom::Ref(a), Atom::Ref(b)) => a == b,
                        (Atom::Null, Atom::Null) | (Atom::Undefined, Atom::Undefined) => true,
                        (Atom::Bool(a), Atom::Bool(b)) => a == b,
                        _ => false,
                    };
                    if let Some((_, old)) = entries.iter_mut().find(|(k, _)| equal(k, &key)) {
                        *old = v
                    } else {
                        entries.push((key, v))
                    }
                } else if let Some(path) = op["readonly"].as_array() {
                    let id = reference(&selector(&g, &path[..path.len() - 1]));
                    let key = path.last().unwrap().as_str().unwrap();
                    if let Some(i) = g.nodes[id as usize]
                        .properties()
                        .iter()
                        .position(|p| g.strings[p.key as usize].is(key))
                    {
                        g.nodes[id as usize].properties_mut()[i].flags &= !2;
                    } else {
                        let initial = if key == "length" {
                            if let Node::Array { length, .. } = &g.nodes[id as usize] {
                                Atom::Number(*length as f64)
                            } else {
                                Atom::Undefined
                            }
                        } else {
                            Atom::Undefined
                        };
                        set(&mut g, id, key, initial);
                        g.nodes[id as usize]
                            .properties_mut()
                            .last_mut()
                            .unwrap()
                            .flags = 0
                    }
                } else {
                    panic!("operation")
                };
                doc.apply(doc.revision(), g).unwrap();
                serde_json::json!({"result":{"root":["undefined"],"nodes":[]}})
            };
            let expected = if step.get("error").is_some() {
                serde_json::json!({"error":step["error"]})
            } else {
                serde_json::json!({"result":step["result"]})
            };
            assert_eq!(actual, expected, "result {} {:?}", c["id"], op);
            assert_eq!(
                canonical(&doc.snapshot().unwrap()),
                step["graph"],
                "graph {} {:?}",
                c["id"],
                op
            );
        }
        for expected in c["outputs"].as_array().unwrap() {
            let mut o = RenderOptions::default();
            o.render.max_width = expected["maxWidth"].as_f64();
            let before = fingerprint(&doc.snapshot().unwrap());
            let actual = doc
                .render_operation(doc.revision(), &o, &mut MetricsResources)
                .unwrap()
                .result;
            if expected.get("error").is_some() {
                let e = actual.unwrap_err();
                assert_eq!(public_error(&e), expected["error"], "render {}", c["id"]);
            } else {
                let r = actual.unwrap().rendered;
                assert_eq!(
                    hash(&r.svg),
                    expected["svgSha256"].as_str().unwrap(),
                    "svg {} max {:?}",
                    c["id"],
                    o.render.max_width
                );
                assert_eq!(
                    (r.width, r.height),
                    (
                        expected["width"].as_f64().unwrap(),
                        expected["height"].as_f64().unwrap()
                    )
                );
                assert_eq!(serde_json::to_value(&r.links).unwrap(), expected["links"]);
            }
            assert_eq!(fingerprint(&doc.snapshot().unwrap()), before);
        }
    }
}

struct FailingHost;
impl RenderResources for FailingHost {
    fn text_width(&mut self, _: TextRequest<'_>) -> Result<f64, PeleError> {
        Err(PeleError::new("host width failed", ErrorCode::Semantic))
    }
}
#[test]
fn native_cynefin_fields_aliases_retained_owner_pixels_seed_and_recovery() {
    let source = "cynefin-beta\ntitle Decisions\ncomplex\n\"Investigate\"\ncomplicated\n\"Expert\"\nclear\n\"Checklist\"\nchaotic\n\"Stabilize\"\nconfusion\n\"A\"\n\"B\"\n\"C\"\n\"D\"\ncomplex --> clear : \"Learned\"";
    let parses = Arc::new(AtomicUsize::new(0));
    let renders = Arc::new(AtomicUsize::new(0));
    let mut engine = PublicEngine::empty();
    engine.register(Counted {
        parses: parses.clone(),
        renders: renders.clone(),
    });
    let mut doc = engine.parse(source, &Default::default()).unwrap();
    assert_eq!(doc.model_schema().id, "pele/cynefin@1");
    assert!(doc.model_schema().prototypes.is_empty());
    assert!(doc.model_schema().methods.is_empty());
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    assert!(matches!(g.nodes[r as usize], Node::Object { .. }));
    assert_eq!(
        keys(&g, r),
        [
            "type",
            "title",
            "accTitle",
            "accDescr",
            "domains",
            "transitions"
        ]
    );
    assert!(g.nodes[r as usize]
        .properties()
        .iter()
        .all(|p| p.flags == 7));
    let item = reference(&selector(
        &g,
        serde_json::json!(["domains",{"map":"complex"},"items",0])
            .as_array()
            .unwrap(),
    ));
    let label = string(&mut g, "Inspect carefully");
    set(&mut g, item, "label", label);
    let title = string(&mut g, "Revised decisions");
    set(&mut g, r, "title", title);
    let lie = string(&mut g, "pie");
    set(&mut g, r, "type", lie);
    let raw = g.strings.len() as u32;
    g.strings.push(JsString(vec![0xd800, 65]));
    set(&mut g, r, "rawExtra", Atom::String(raw));
    set(
        &mut g,
        r,
        "nanExtra",
        Atom::Number(f64::from_bits(0x7ff8000000000042)),
    );
    let mut at = r;
    for _ in 0..20_000 {
        let next = object(&mut g);
        set(&mut g, at, "extra", Atom::Ref(next));
        at = next;
    }
    set(&mut g, at, "cycle", Atom::Ref(r));
    doc.apply(doc.revision(), g).unwrap();
    let mut original = Engine::empty();
    original.register(Cynefin);
    let expected = original
        .render_source(
            &source
                .replace("Investigate", "Inspect carefully")
                .replace("title Decisions", "title Revised decisions"),
            &Default::default(),
            &mut MetricsResources,
        )
        .unwrap();
    let actual = doc
        .render(&Default::default(), &mut MetricsResources)
        .unwrap();
    assert_eq!(actual.diagram_type.as_str(), "cynefin");
    assert_eq!(actual.rendered.svg, expected.rendered.svg);
    engine.register(Cynefin);
    drop(engine);
    let mut native = RenderOptions::default();
    native.render.native_theme = Some(NativeTheme::default());
    native.parse.preparation.limit = 0;
    native.parse.max_edges = 0;
    let painted = doc.render(&native, &mut MetricsResources).unwrap().rendered;
    assert!(!painted.svg.contains("var(--"));
    assert!(!painted.svg.contains("color-mix("));
    let xml = roxmltree::Document::parse(&painted.svg).unwrap();
    for (class, count) in [
        ("pele-cynefin-region", 5),
        ("pele-cynefin-domain", 5),
        ("pele-cynefin-cliff", 1),
        ("pele-edge", 1),
        ("pele-node pele-cynefin-overflow", 1),
    ] {
        assert_eq!(
            xml.descendants()
                .filter(|n| n.attribute("class") == Some(class))
                .count(),
            count
        );
    }
    let tree = resvg::usvg::Tree::from_str(&painted.svg, &Default::default()).unwrap();
    let mut pixels = resvg::tiny_skia::Pixmap::new(
        tree.size().width().ceil() as u32,
        tree.size().height().ceil() as u32,
    )
    .unwrap();
    resvg::render(
        &tree,
        resvg::tiny_skia::Transform::identity(),
        &mut pixels.as_mut(),
    );
    assert!(
        pixels
            .pixels()
            .iter()
            .filter(|p| p.alpha() > 0 && p.red() < 160 && p.green() < 160 && p.blue() < 160)
            .count()
            > 1000
    );
    native.render.max_width = Some(200.);
    let narrow = doc.render(&native, &mut MetricsResources).unwrap().rendered;
    assert_eq!(
        (narrow.width, narrow.height),
        (painted.width, painted.height)
    );
    native.render.id_prefix = Some("changed-seed".into());
    let changed = doc.render(&native, &mut MetricsResources).unwrap().rendered;
    let changed_xml = roxmltree::Document::parse(&changed.svg).unwrap();
    let boundary = |xml: &roxmltree::Document<'_>| {
        xml.descendants()
            .find(|n| n.attribute("class") == Some("pele-cynefin-boundaries"))
            .unwrap()
            .children()
            .find(|n| n.is_element())
            .unwrap()
            .attribute("d")
            .unwrap()
            .to_string()
    };
    assert_ne!(boundary(&xml), boundary(&changed_xml));
    let before = fingerprint(&doc.snapshot().unwrap());
    assert!(doc
        .render(&Default::default(), &mut FailingHost)
        .unwrap_err()
        .message
        .contains("host width failed"));
    let mut limited = RenderOptions::default();
    limited.render.output_limit = Some(20);
    assert_eq!(
        doc.render(&limited, &mut MetricsResources)
            .unwrap_err()
            .code,
        ErrorCode::Limit
    );
    assert_eq!(fingerprint(&doc.snapshot().unwrap()), before);
    assert_eq!(
        doc.render(&Default::default(), &mut MetricsResources)
            .unwrap()
            .rendered
            .svg,
        actual.rendered.svg
    );
    assert_eq!(parses.load(Ordering::SeqCst), 1);
    assert!(renders.load(Ordering::SeqCst) >= 7);
}
#[test]
fn cynefin_sparse_ignored_tail_limits_typed_errors_and_recovery() {
    let mut engine = PublicEngine::empty();
    engine.register(Cynefin);
    let mut doc = engine
        .parse(
            "cynefin-beta\nconfusion\n\"A\"\n\"B\"\n\"C\"",
            &Default::default(),
        )
        .unwrap();
    let baseline = doc.snapshot().unwrap();
    let mut g = baseline.clone();
    let items = reference(&selector(
        &g,
        serde_json::json!(["domains",{"map":"confusion"},"items"])
            .as_array()
            .unwrap(),
    ));
    if let Node::Array { length, .. } = &mut g.nodes[items as usize] {
        *length = 10_000;
    }
    set(&mut g, items, "9999", Atom::Ref(root(&baseline)));
    doc.apply(doc.revision(), g).unwrap();
    let output = doc
        .render(&Default::default(), &mut MetricsResources)
        .unwrap();
    assert!(output.rendered.svg.contains("+9997 more"));
    let mut g = doc.snapshot().unwrap();
    if let Node::Array { length, .. } = &mut g.nodes[items as usize] {
        *length = 1_000_001;
    }
    doc.apply(doc.revision(), g).unwrap();
    assert_eq!(
        doc.render(&Default::default(), &mut MetricsResources)
            .unwrap_err()
            .code,
        ErrorCode::Limit
    );
    let mut g = baseline.clone();
    g.nodes[items as usize]
        .properties_mut()
        .retain(|p| !g.strings[p.key as usize].is("0"));
    doc.apply(doc.revision(), g).unwrap();
    let op = doc
        .render_operation(doc.revision(), &Default::default(), &mut MetricsResources)
        .unwrap();
    assert!(matches!(
        op.result,
        Err(PublicError::JavaScript {
            name: JavaScriptErrorKind::TypeError,
            ..
        })
    ));
    let mut g = baseline.clone();
    let r = root(&g);
    let raw = g.strings.len() as u32;
    g.strings.push(JsString(vec![0xd800]));
    set(&mut g, r, "title", Atom::String(raw));
    doc.apply(doc.revision(), g).unwrap();
    assert!(doc
        .render(&Default::default(), &mut MetricsResources)
        .unwrap_err()
        .message
        .contains("UTF16"));
    doc.apply(doc.revision(), baseline).unwrap();
    assert!(doc
        .render(&Default::default(), &mut MetricsResources)
        .is_ok());
}

